CREATE TABLE [dbo].[ccTimetable](	  [id] INT NOT NULL	, [user_id] SMALLINT NOT NULL	, [startdate] SMALLDATETIME NOT NULL	, [enddate] SMALLDATETIME NOT NULL	, [fixed] BIT NOT NULL DEFAULT(1)	, [days] SMALLINT NOT NULL DEFAULT(31)	, CONSTRAINT [PK_Timetable] PRIMARY KEY ([id] ASC))ALTER TABLE [dbo].[ccTimetable] WITH NOCHECK ADD CONSTRAINT [FK_Timetable_User] FOREIGN KEY([user_id]) REFERENCES [dbo].[ccUsers] ([User_id])ALTER TABLE [dbo].[ccTimetable] CHECK CONSTRAINT [FK_Timetable_User]